  "content": "def are_email_bodies_in_str(emails: list[str], email_str: Email) -> bool:
    email_str_no_newline = email_str.body.replace("\n", "")
    for email_body in emails:
        if email_body.replace("\n", "") not in email_str_no_newline:
            return False
    return True
